import { paths, withBasePath } from '@/modules/url';
import { DISPLAY_CJK, displayFontCss } from './display-cjk';

/**
 * The CJK display face subsets of a locale (§11.1.2), generated by content:build. React hoists
 * the link into <head>; each @font-face has an exact unicode-range, so a page downloads only the
 * files that hold its own title's characters. Renders nothing for other locales.
 */
export function DisplayFontStylesheet({ code }: { code: string }) {
  if (!DISPLAY_CJK[code]) return null;
  return <link rel="stylesheet" href={withBasePath(paths.generated(displayFontCss(code)))} precedence="default" />;
}
